// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(uint64 timeDelta, uint64 blockOffset, address actor) public {
        vm.assume(timeDelta > 0);
        vm.assume(actor != address(0));

        uint256 amt = 10 ether;
        vm.deal(actor, amt);

        vm.warp(block.timestamp + timeDelta);
        uint64 targetBlock = uint64(block.number) + (blockOffset % 100);
        vm.roll(uint256(targetBlock));

        vm.prank(actor);
        (bool ok,) = address(c).call{value: amt}("");

        if (block.number % 15 != 0) {
            assertTrue(ok);
            assertTrue(address(c).balance == amt);
        } else {
            assertTrue(ok);
        }
    }
}
